// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "fallback call failed");

        uint balanceBefore = address(c).balance;

        vm.deal(address(this), 0);
        c.sendMoney(address(0xdead), 1 ether, "");

        assertEq(address(c).balance, balanceBefore - 1 ether);
    }
}
